create or replace function investing.rl8c_jsonb_has_number_v1(p_value jsonb) returns boolean language sql immutable strict set search_path = pg_catalog as $$
  select case jsonb_typeof(p_value) when 'number' then true when 'array' then exists (select 1 from pg_catalog.jsonb_array_elements(p_value) as e(value) where investing.rl8c_jsonb_has_number_v1(e.value)) when 'object' then exists (select 1 from pg_catalog.jsonb_each(p_value) as e(key, value) where investing.rl8c_jsonb_has_number_v1(e.value)) else false end
$$;

create or replace function investing.rl8c_canonical_jsonb_v1(p_value jsonb) returns text language plpgsql immutable strict set search_path = pg_catalog as $$
declare v_type text; v_out text;
begin
  v_type := pg_catalog.jsonb_typeof(p_value);
  if v_type = 'null' then return 'null'; elsif v_type = 'boolean' then return lower(p_value::text); elsif v_type = 'number' then raise exception 'RL-8C canonical JSON forbids numbers'; elsif v_type = 'string' then return pg_catalog.to_jsonb(p_value #>> '{}')::text; elsif v_type = 'array' then select '[' || coalesce(pg_catalog.string_agg(investing.rl8c_canonical_jsonb_v1(e.value), ',' order by e.ordinality), '') || ']' into v_out from pg_catalog.jsonb_array_elements(p_value) with ordinality as e(value, ordinality); return v_out; elsif v_type = 'object' then select '{' || coalesce(pg_catalog.string_agg(pg_catalog.to_jsonb(e.key)::text || ':' || investing.rl8c_canonical_jsonb_v1(e.value), ',' order by e.key collate "C"), '') || '}' into v_out from pg_catalog.jsonb_each(p_value) as e(key, value); return v_out; end if;
  raise exception 'RL-8C canonical JSON unsupported jsonb type: %', v_type;
end;
$$;

create or replace function investing.rl8c_sha256_hex_v1(p_hash_domain text, p_canonical_payload jsonb) returns text language sql immutable strict set search_path = pg_catalog, extensions as $$
  select upper(pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_hash_domain || E'\n' || investing.rl8c_canonical_jsonb_v1(p_canonical_payload), 'UTF8'), 'sha256'), 'hex'))
$$;



create or replace function investing.rl8c_jsonb_object_has_exact_keys_v1(p_value jsonb, p_keys text[]) returns boolean language sql immutable strict set search_path = pg_catalog as $$
  select jsonb_typeof(p_value) = 'object' and (select array_agg(k order by k) from jsonb_object_keys(p_value) as k) = (select array_agg(k order by k) from unnest(p_keys) as k)
$$;

create or replace function investing.rl8c_hashref_matches_v1(p_ref jsonb, p_domain text, p_hash_hex text) returns boolean language sql immutable set search_path = pg_catalog as $$
  select p_ref is not null and p_ref <> 'null'::jsonb and jsonb_typeof(p_ref) = 'object' and investing.rl8c_jsonb_object_has_exact_keys_v1(p_ref, array['hashAlgorithm','hashDomain','hashHex','hashVersion']) and p_ref->>'hashAlgorithm' = 'SHA-256' and p_ref->>'hashDomain' = p_domain and p_ref->>'hashVersion' = 'SYNTRAKE_SHA256_V1' and p_ref->>'hashHex' = p_hash_hex and p_hash_hex ~ '^[0-9A-F]{64}$'
$$;

create or replace function investing.rl8c_hashref_presence_v1(p_ref jsonb, p_domain text, p_identity_id uuid, p_hash_hex text) returns boolean language sql immutable set search_path = pg_catalog as $$
  select case when p_ref is null or p_ref = 'null'::jsonb then p_identity_id is null and p_hash_hex is null else p_identity_id is not null and p_hash_hex is not null and investing.rl8c_hashref_matches_v1(p_ref, p_domain, p_hash_hex) end
$$;

create or replace function investing.rl8c_validate_gate_outcomes_v1(p_gate_outcomes jsonb, p_requires_complete boolean) returns boolean language sql immutable strict set search_path = pg_catalog as $$
  with expected(gate_id) as (values ('GATE_ACCEPTED_EXECUTION_RESULT'), ('GATE_AUTHORITY_AND_TENANCY'), ('GATE_EVIDENCE_COMPLETENESS'), ('GATE_EVIDENCE_OBJECT_BINDING'), ('GATE_LINEAGE_INTEGRITY'), ('GATE_METRIC_RESULT_SET_V2'), ('GATE_PROTOCOL_COMPATIBILITY'), ('GATE_RL7_ROBUSTNESS_COMPARISON'), ('GATE_SUBJECT_IDENTITY'), ('GATE_VALIDATION_ASSESSMENT'), ('GATE_VALIDATION_RESULT')), gates as (select value from jsonb_array_elements(case when jsonb_typeof(p_gate_outcomes) = 'array' then p_gate_outcomes else '[]'::jsonb end))
  select case when jsonb_typeof(p_gate_outcomes) <> 'array' then false when not p_requires_complete then p_gate_outcomes = '[]'::jsonb else (select count(*) = 11 from gates) and (select count(distinct value->>'gateId') = 11 from gates) and not exists (select 1 from gates g where jsonb_typeof(g.value) <> 'object' or not investing.rl8c_jsonb_object_has_exact_keys_v1(g.value, array['evidence','gateId','reasons','status']) or g.value->>'gateId' not in (select gate_id from expected) or g.value->>'status' not in ('FAIL','INCOMPATIBLE_EVIDENCE','INSUFFICIENT_EVIDENCE','PASS','UNAVAILABLE') or jsonb_typeof(g.value->'evidence') <> 'array' or jsonb_typeof(g.value->'reasons') <> 'array') and not exists (select 1 from expected e where not exists (select 1 from gates g where g.value->>'gateId' = e.gate_id)) end
$$;

create or replace function investing.rl8c_validate_protocol_payload_shape_v1(p_payload jsonb) returns boolean language sql immutable strict set search_path = pg_catalog as $$
  select jsonb_typeof(p_payload) = 'object' and investing.rl8c_jsonb_object_has_exact_keys_v1(p_payload, array['compatibleMetricRegistryVersion','decisionPrecedence','gateEvidenceMapping','gateStatusVocabulary','gateVocabulary','protocolId','reasonVocabulary','requiredEvidenceClasses','requiredRl7PolicyId','rl7Required','schemaVersion','stateVocabulary','transitionGraph']) and p_payload->>'schemaVersion' = 'SCIENTIFIC_PROMOTION_PROTOCOL_V1' and jsonb_typeof(p_payload->'protocolId') = 'string' and jsonb_typeof(p_payload->'requiredEvidenceClasses') = 'array' and jsonb_typeof(p_payload->'compatibleMetricRegistryVersion') = 'string' and jsonb_typeof(p_payload->'requiredRl7PolicyId') = 'string' and jsonb_typeof(p_payload->'rl7Required') = 'boolean' and jsonb_typeof(p_payload->'stateVocabulary') = 'array' and jsonb_typeof(p_payload->'gateVocabulary') = 'array' and jsonb_typeof(p_payload->'gateStatusVocabulary') = 'array' and jsonb_typeof(p_payload->'reasonVocabulary') = 'array' and jsonb_typeof(p_payload->'gateEvidenceMapping') = 'array' and jsonb_typeof(p_payload->'decisionPrecedence') = 'array' and jsonb_typeof(p_payload->'transitionGraph') = 'array'
$$;

create or replace function investing.rl8c_validate_transition_payload_shape_v1(p_payload jsonb, p_predecessor_state text, p_resulting_state text, p_protocol_hash_hex text, p_subject_experiment_hash_hex text, p_subject_experiment_parameters_hash_hex text, p_subject_research_ir_hash_hex text, p_predecessor_identity_id uuid, p_predecessor_hash_hex text, p_rejected_identity_id uuid, p_rejected_hash_hex text, p_supersedes_identity_id uuid, p_supersedes_hash_hex text, p_successor_protocol_identity_id uuid, p_successor_protocol_hash_hex text, p_successor_root_identity_id uuid, p_successor_root_hash_hex text, p_run_input_identity_id uuid, p_run_input_hash_hex text, p_result_identity_id uuid, p_result_hash_hex text, p_evidence_object_identity_id uuid, p_evidence_object_hash_hex text, p_validation_protocol_identity_id uuid, p_validation_protocol_hash_hex text, p_validation_result_identity_id uuid, p_validation_result_hash_hex text, p_validation_assessment_protocol_identity_id uuid, p_validation_assessment_protocol_hash_hex text, p_validation_assessment_result_identity_id uuid, p_validation_assessment_result_hash_hex text, p_robustness_comparison_protocol_identity_id uuid, p_robustness_comparison_protocol_hash_hex text, p_robustness_comparison_result_identity_id uuid, p_robustness_comparison_result_hash_hex text) returns boolean language sql immutable set search_path = pg_catalog as $$
  select jsonb_typeof(p_payload) = 'object'
    and investing.rl8c_jsonb_object_has_exact_keys_v1(p_payload, array['evidenceSnapshot','gateOutcomes','predecessorState','predecessorTransition','protocol','rejectedTransition','resultingState','schemaVersion','subject','supersededByChain','supersedes','transitionReasons'])
    and p_payload->>'schemaVersion' = 'SCIENTIFIC_PROMOTION_TRANSITION_V1' and p_payload->>'predecessorState' = p_predecessor_state and p_payload->>'resultingState' = p_resulting_state
    and jsonb_typeof(p_payload->'protocol') = 'object' and jsonb_typeof(p_payload->'subject') = 'object' and jsonb_typeof(p_payload->'evidenceSnapshot') = 'object' and jsonb_typeof(p_payload->'gateOutcomes') = 'array' and jsonb_typeof(p_payload->'transitionReasons') = 'array'
    and investing.rl8c_hashref_matches_v1(p_payload->'protocol', 'SYNTRAKE:SCIENTIFIC_PROMOTION_PROTOCOL:V1', p_protocol_hash_hex)
    and investing.rl8c_hashref_matches_v1(p_payload#>'{subject,subjectExperiment}', 'SYNTRAKE:EXPERIMENT:V1', p_subject_experiment_hash_hex)
    and investing.rl8c_hashref_matches_v1(p_payload#>'{subject,subjectExperimentParameters}', 'SYNTRAKE:EXPERIMENT_PARAMETERS:V1', p_subject_experiment_parameters_hash_hex)
    and investing.rl8c_hashref_matches_v1(p_payload#>'{subject,subjectResearchIr}', 'SYNTRAKE:RESEARCH_IR:V1', p_subject_research_ir_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload->'predecessorTransition', 'SYNTRAKE:SCIENTIFIC_PROMOTION_TRANSITION:V1', p_predecessor_identity_id, p_predecessor_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload->'rejectedTransition', 'SYNTRAKE:SCIENTIFIC_PROMOTION_TRANSITION:V1', p_rejected_identity_id, p_rejected_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload->'supersedes', 'SYNTRAKE:SCIENTIFIC_PROMOTION_TRANSITION:V1', p_supersedes_identity_id, p_supersedes_hash_hex)
    and case when p_payload->'supersededByChain' is null or p_payload->'supersededByChain' = 'null'::jsonb then p_successor_protocol_identity_id is null and p_successor_protocol_hash_hex is null and p_successor_root_identity_id is null and p_successor_root_hash_hex is null else jsonb_typeof(p_payload->'supersededByChain') = 'object' and investing.rl8c_hashref_presence_v1(p_payload#>'{supersededByChain,successorProtocol}', 'SYNTRAKE:SCIENTIFIC_PROMOTION_PROTOCOL:V1', p_successor_protocol_identity_id, p_successor_protocol_hash_hex) and investing.rl8c_hashref_presence_v1(p_payload#>'{supersededByChain,successorRootTransition}', 'SYNTRAKE:SCIENTIFIC_PROMOTION_TRANSITION:V1', p_successor_root_identity_id, p_successor_root_hash_hex) end
    and investing.rl8c_hashref_presence_v1(p_payload#>'{evidenceSnapshot,runInput}', 'SYNTRAKE:RUN_INPUT:V1', p_run_input_identity_id, p_run_input_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload#>'{evidenceSnapshot,result}', 'SYNTRAKE:RESULT:V1', p_result_identity_id, p_result_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload#>'{evidenceSnapshot,evidenceObject}', 'SYNTRAKE:EVIDENCE_OBJECT:V1', p_evidence_object_identity_id, p_evidence_object_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload#>'{evidenceSnapshot,validationProtocol}', 'SYNTRAKE:VALIDATION_PROTOCOL:V1', p_validation_protocol_identity_id, p_validation_protocol_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload#>'{evidenceSnapshot,validationResult}', 'SYNTRAKE:VALIDATION_RESULT:V1', p_validation_result_identity_id, p_validation_result_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload#>'{evidenceSnapshot,validationAssessmentProtocol}', 'SYNTRAKE:VALIDATION_ASSESSMENT_PROTOCOL:V1', p_validation_assessment_protocol_identity_id, p_validation_assessment_protocol_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload#>'{evidenceSnapshot,validationAssessmentResult}', 'SYNTRAKE:VALIDATION_ASSESSMENT_RESULT:V1', p_validation_assessment_result_identity_id, p_validation_assessment_result_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload#>'{evidenceSnapshot,robustnessComparisonProtocol}', 'SYNTRAKE:EXPERIMENT_COMPARISON_PROTOCOL:V1', p_robustness_comparison_protocol_identity_id, p_robustness_comparison_protocol_hash_hex)
    and investing.rl8c_hashref_presence_v1(p_payload#>'{evidenceSnapshot,robustnessComparisonResult}', 'SYNTRAKE:EXPERIMENT_COMPARISON_RESULT:V1', p_robustness_comparison_result_identity_id, p_robustness_comparison_result_hash_hex)
    and case when p_predecessor_state = 'DRAFT_RESEARCH' and p_resulting_state = 'EXECUTED' then p_predecessor_identity_id is null and p_run_input_identity_id is not null and p_result_identity_id is not null and p_evidence_object_identity_id is null and p_validation_protocol_identity_id is null and p_validation_result_identity_id is null and p_validation_assessment_protocol_identity_id is null and p_validation_assessment_result_identity_id is null and p_robustness_comparison_protocol_identity_id is null and p_robustness_comparison_result_identity_id is null and p_payload->'gateOutcomes' = '[]'::jsonb and p_payload->'transitionReasons' = '[]'::jsonb and p_payload->'supersedes' = 'null'::jsonb and p_payload->'rejectedTransition' = 'null'::jsonb and p_payload->'supersededByChain' = 'null'::jsonb else true end
    and case when p_predecessor_state in ('EXECUTED','INSUFFICIENT_EVIDENCE','PROMOTION_ELIGIBLE','REJECTED') and p_resulting_state in ('INSUFFICIENT_EVIDENCE','VALIDATION_FAILED','VALIDATION_PASSED') then p_run_input_identity_id is not null and p_result_identity_id is not null and investing.rl8c_validate_gate_outcomes_v1(p_payload->'gateOutcomes', true) else investing.rl8c_validate_gate_outcomes_v1(p_payload->'gateOutcomes', p_resulting_state in ('PROMOTION_ELIGIBLE','REJECTED')) end
$$;

create or replace function investing.reject_research_scientific_promotion_update_delete_v1() returns trigger language plpgsql security invoker set search_path = pg_catalog as $$
begin raise exception 'research scientific promotion identities are append-only'; end;
$$;

