grant execute on function investing.rl8c_jsonb_has_number_v1(jsonb) to investing_rl8_writer;
grant execute on function investing.rl8c_canonical_jsonb_v1(jsonb) to investing_rl8_writer;
grant execute on function investing.rl8c_sha256_hex_v1(text, jsonb) to investing_rl8_writer;
